def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def sum_not_prime(nums):
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if is_prime(nums[i] + nums[j]):
                return False
    return True

numbers = list(range(1, 51))
result = []
for i in range(len(numbers)):
    subset = numbers[:i] + numbers[i+1:]
    if sum_not_prime(subset):
        result += [numbers[i]]
        break

# Now we need to remove 24 more numbers
for i in range(len(numbers)):
    if numbers[i] not in result:
        result.append(numbers[i])
        subset = [x for x in numbers if x not in result]
        if sum_not_prime(subset):
            continue
        else:
            result.pop()
            break

print(result)
