def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def sum_not_prime(nums):
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if is_prime(nums[i] + nums[j]):
                return False
    return True

numbers = list(range(1, 51))

result = []
for n in numbers:
    if is_prime(n):
        result.append(n)
    else:
        for m in numbers:
            if n != m and is_prime(n + m):
                result.append(n)
                break

# Remove duplicates and sort the list
result = sorted(list(set(result)))

# Remove the 25th number from the list
result.pop()

print(result)
